#include <vector>

int sumAll(const std::vector<int>& ws) {
    int s = 0;
    for (int i = 0; i < static_cast<int>(ws.size()); i++) {
        s += ws[i];
    }
    return s;
}

int biggest(const std::vector<int>& ws) {
    int best = 0;
    for (int i = 0; i < static_cast<int>(ws.size()); i++) {
        if (ws[i] > best) {
            best = ws[i];
        }
    }
    return best;
}

